// ── Code-basis normalization — applied to EVERY record (curated + expanded) ───
// Fire setbacks are CODE-driven, not a per-AHJ opinion: they come from the
// adopted-code table (JURISDICTION_DATA, per-state IFC/IRC posture — e.g.
// AZ/NV/NM/TX/UT use an 18" perimeter, most states 36"/18" ridge), never a
// bulk-onboarding default. This guarantees setbacks use real logic everywhere.
// CA (NEC 2023 statewide) and FL (ASCE 7 wind floor) invariants are also enforced;
// both are idempotent on the curated set. Per-AHJ specifics that ARE genuinely
// local (contact, fees, utility, special requirements, local NEC) are preserved.
function applyCodeBasis(r: AhjRecord, provenance: 'curated' | 'expanded'): AhjRecord {
  const code = JURISDICTION_DATA[r.stateCode];
  return {
    ...r,
    necVersion: r.stateCode === 'CA' ? '2023' : r.necVersion,
    windSpeedMph: r.stateCode === 'FL' ? Math.max(r.windSpeedMph, 130) : r.windSpeedMph,
    // Real code logic — fall back to the record only where the table has no entry
    // (e.g. Puerto Rico / territories, which JURISDICTION_DATA doesn't cover).
    roofSetbackInches: code ? code.roofSetbackInches : r.roofSetbackInches,
    ridgeSetbackInches: code ? code.ridgeSetbackInches : r.ridgeSetbackInches,
    dataProvenance: provenance,
  };
}

const ahjPlaceKey = (r: AhjRecord) =>
  (r.stateCode + '|' + r.county + '|' + r.city).toLowerCase().trim();

// Curated authoritative; an expanded record is dropped when it duplicates a
// curated (or already-added) record by id OR by (state, county, city).
function mergeAhj(curated: AhjRecord[], expanded: AhjRecord[]): AhjRecord[] {
  const out: AhjRecord[] = curated.map(r => applyCodeBasis(r, 'curated'));
  const seenId = new Set(out.map(r => r.id));
  const seenPlace = new Set(out.map(ahjPlaceKey));
  for (const raw of expanded) {
    const r = applyCodeBasis(raw, 'expanded');
    if (seenId.has(r.id) || seenPlace.has(ahjPlaceKey(r))) continue;
    seenId.add(r.id);
    seenPlace.add(ahjPlaceKey(r));
    out.push(r);
  }
  return out;
}

// ============================================================
// NATIONAL AHJ DATABASE (curated then expanded; curated wins)
// ============================================================
export const AHJ_NATIONAL: AhjRecord[] = mergeAhj(AHJ_CURATED, AHJ_EXPANDED);


// ── Search functions ──────────────────────────────────────────────────────────

export function searchAhj(query: {
  stateCode?: string;
  county?: string;
  city?: string;
  zipCode?: string;
  text?: string;
}): AhjRecord[] {
  let results = AHJ_NATIONAL;

  if (query.stateCode) {
    results = results.filter(a => a.stateCode.toUpperCase() === query.stateCode!.toUpperCase());
  }

  if (query.city) {
    const cityLower = query.city.toLowerCase();
    const cityMatches = results.filter(a => a.city.toLowerCase().includes(cityLower));
    if (cityMatches.length > 0) results = cityMatches;
  }

  if (query.county) {
    const countyLower = query.county.toLowerCase().replace(' county', '');
    const countyMatches = results.filter(a =>
      a.county.toLowerCase().replace(' county', '').includes(countyLower)
    );
    if (countyMatches.length > 0) results = countyMatches;
  }

  if (query.text) {
    const textLower = query.text.toLowerCase();
    results = results.filter(a =>
      a.ahjName.toLowerCase().includes(textLower) ||
      a.city.toLowerCase().includes(textLower) ||
      a.county.toLowerCase().includes(textLower) ||
      a.stateName.toLowerCase().includes(textLower) ||
      a.utilityName.toLowerCase().includes(textLower)
    );
  }

  return results;
}

export function getAhjById(id: string): AhjRecord | null {
  return AHJ_NATIONAL.find(a => a.id === id) || null;
}

export function getAhjsByState(stateCode: string): AhjRecord[] {
  return AHJ_NATIONAL.filter(a => a.stateCode.toUpperCase() === stateCode.toUpperCase());
}

/**
 * Resolve the county-wide AHJ for a state + county (prefers the county /
 * unincorporated record over a specific city in that county).
 */
export function getAhjByCounty(stateCode: string, county: string): AhjRecord | null {
  if (!stateCode || !county) return null;
  // Exact normalized county match — do NOT use searchAhj here: its county filter
  // widens to the whole state when nothing matches, which would silently return
  // the first record (Cook/Chicago) for an unknown county.
  const target = county.trim().toLowerCase().replace(/\s+county$/, '');
  if (!target) return null;
  const matches = getAhjsByState(stateCode).filter(
    a => a.county.toLowerCase().replace(/\s+county$/, '') === target,
  );
  if (matches.length === 0) return null;
  return matches.find(a => a.ahjType === 'county' || a.city.toLowerCase() === 'unincorporated')
    ?? matches[0];
}

/**
 * Resolve an AHJ from an address, optionally helped by structured hints
 * (county/city/stateCode the caller already has from geocoding).
 *
 * Resolution order: county hint → city → county parsed from text → single-AHJ
 * state. Critically, it NO LONGER falls back to "the first AHJ in the state":
 * that silently returned Cook County / Chicago for EVERY unmatched Illinois
 * address (e.g. Wood River, which is Madison County), poisoning the planset's
 * wind/snow/utility/permit data. When it can't localize, it returns null and
 * the caller uses neutral code-minimum defaults instead of a wrong jurisdiction.
 */
export function getAhjByAddress(
  address: string,
  hint?: { stateCode?: string; county?: string; city?: string },
): AhjRecord | null {
  const stateMatch = address?.match(/,\s*([A-Z]{2})(?:\s+\d{5})?(?:\s*,|\s*$)/);
  const stateCode = (hint?.stateCode || stateMatch?.[1] || '').toUpperCase();
  if (!stateCode) return null;

  // 1) County hint — the most reliable geographic key (Wood River → Madison).
  if (hint?.county) {
    const byCounty = getAhjByCounty(stateCode, hint.county);
    if (byCounty) return byCounty;
  }

  // 2) City — hint, else parsed from the address (strip trailing country + "ST 12345").
  let city = hint?.city ?? null;
  if (!city && address) {
    const parts = address.split(',').map(p => p.trim()).filter(Boolean)
      .filter(p => !/^(usa|united states)$/i.test(p) && !/^[A-Z]{2}\s+\d{5}/.test(p));
    city = parts.length >= 1 ? parts[parts.length - 1] : null;
    if (city && /^[A-Z]{2}$/.test(city) && parts.length >= 2) city = parts[parts.length - 2];
  }
  if (city) {
    // searchAhj returns ALL state records when the city doesn't match, so re-filter
    // to an actual city-name hit before accepting it (never accept a non-match).
    const cityLower = city.toLowerCase();
    const exact = searchAhj({ stateCode, city }).filter(a => a.city.toLowerCase().includes(cityLower));
    if (exact.length > 0) return exact[0];
  }

  // 3) County parsed from the address text ("... Madison County, IL ...").
  const countyTextMatch = address?.match(/([A-Za-z][A-Za-z .'-]*?)\s+County/i);
  if (countyTextMatch) {
    const byCounty = getAhjByCounty(stateCode, countyTextMatch[1].trim());
    if (byCounty) return byCounty;
  }

  // 4) Only auto-pick when the state has exactly one AHJ; otherwise null (no guess).
  const stateResults = getAhjsByState(stateCode);
  return stateResults.length === 1 ? stateResults[0] : null;
}

export function getTotalAhjCount(): number {
  return AHJ_NATIONAL.length;
}

export function getStatesSummary(): { stateCode: string; stateName: string; count: number }[] {
  const map = new Map<string, { stateName: string; count: number }>();
  for (const a of AHJ_NATIONAL) {
    const existing = map.get(a.stateCode);
    if (existing) {
      existing.count++;
    } else {
      map.set(a.stateCode, { stateName: a.stateName, count: 1 });
    }
  }
  return Array.from(map.entries())
    .map(([stateCode, v]) => ({ stateCode, ...v }))
    .sort((a, b) => a.stateCode.localeCompare(b.stateCode));
}
